-- to guests: visits
('visit_saved', 'guest', 30, 'Request saved, not finished (yellow), sent right away', 'Your request is saved but not finished',
 'Thanks, [first name]! Your request for [a type] on [date] at [time] is saved but not finished yet. Please agree to each house rule and answer the questions so Micala and Gabriel can review it. Nothing is approved until you do. Finish here: [link]'),
('visit_incomplete_reminder', 'guest', 31, 'Still not finished, 2 hours later', 'Reminder: your request isn''t finished',
 'Reminder: your request for [a type] on [date] at [time] isn''t finished yet. Please complete it within 24 hours or the time will be released: [link]'),
('visit_expired', 'guest', 32, 'Unfinished request expired', 'Your unfinished request expired',
 'Your unfinished request for [a type] on [date] at [time] has expired, and the time was released. You''re welcome to request again anytime: [link]'),
('visit_submitted', 'guest', 33, 'Request complete, waiting for approval (orange)', 'Your request is in',
 'Thank you, [first name]! Your request for [a type] on [date] at [time] is in. Micala or Gabriel will review it, so please don''t plan on it until you get a confirmation. We''ll email you as soon as there''s an answer. Once approved, the family will share the address with you personally.'),
('visit_approved', 'guest', 34, 'Approved', 'You''re approved!',
