('meal_expired', 'guest', 63, 'Meal Train not confirmed in time', 'Your Meal Train slot was released',
 'Your Meal Train slot on [date] wasn''t confirmed in time and has been released. You''re welcome to sign up again: [link]'),
('meal_reminder_24h', 'guest', 64, 'Meal Train 24 hours before', 'Reminder: you''re bringing [dish] tomorrow',
 'Reminder: you''re bringing [dish] tomorrow, [time window]. Please use the cooler out front and knock or ring the bell. No need to wait. Thank you!'),
('meal_reminder_1h', 'guest', 65, 'Meal Train 1 hour before', 'Thank you for bringing [dish] today',
 'Thank you for bringing [dish] today, [time window]! Please leave it in the cooler out front and knock or ring the bell. No need to wait for an answer.'),
('meal_family_cancelled', 'guest', 66, 'Meal Train: family cancels', 'Your Meal Train slot was cancelled',
 'We''re so sorry, [first name], but your Meal Train slot on [date] has been cancelled. Note: [note]. Thank you for thinking of us!'),
('meal_guest_cancelled', 'guest', 67, 'Meal Train: guest cancels (confirmation)', 'Your Meal Train slot was cancelled',
